import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/polymer/v3_0/iron-flex-layout/iron-flex-layout-classes.js";import"./certificate_entry.js";import"./certificate_shared.css.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{assertNotReached}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./certificate_list.html.js";import{CertificateAction,CertificateActionEvent}from"./certificate_manager_types.js";import{CertificatesBrowserProxyImpl,CertificateType}from"./certificates_browser_proxy.js";const CertificateListElementBase=I18nMixin(PolymerElement);export class CertificateListElement extends CertificateListElementBase{static get is(){return"certificate-list"}static get template(){return getTemplate()}static get properties(){return{certificates:{type:Array,value(){return[]}},certificateType:String,importAllowed:Boolean,isGuest_:{type:Boolean,value(){return loadTimeData.valueExists("isGuest")&&loadTimeData.getBoolean("isGuest")}},isKiosk_:{type:Boolean,value(){return loadTimeData.valueExists("isKiosk")&&loadTimeData.getBoolean("isKiosk")}}}}getDescription_(){if(this.certificates.length===0){return this.i18n("certificateManagerNoCertificates")}switch(this.certificateType){case CertificateType.PERSONAL:return this.i18n("certificateManagerYourCertificatesDescription");case CertificateType.SERVER:return this.i18n("certificateManagerServersDescription");case CertificateType.CA:return this.i18n("certificateManagerAuthoritiesDescription");case CertificateType.OTHER:return this.i18n("certificateManagerOthersDescription");default:assertNotReached()}}canImport_(){return!this.isKiosk_&&this.certificateType!==CertificateType.OTHER&&this.importAllowed}canImportAndBind_(){return!this.isGuest_&&this.certificateType===CertificateType.PERSONAL&&this.importAllowed}onRejected_(anchor,error){if(error===null){return}this.dispatchEvent(new CustomEvent("certificates-error",{bubbles:true,composed:true,detail:{error:error,anchor:anchor}}))}dispatchImportActionEvent_(subnode,anchor){this.dispatchEvent(new CustomEvent(CertificateActionEvent,{bubbles:true,composed:true,detail:{action:CertificateAction.IMPORT,subnode:subnode,certificateType:this.certificateType,anchor:anchor}}))}onImportClick_(e){this.handleImport_(false,e.target)}onImportAndBindClick_(e){this.handleImport_(true,e.target)}handleImport_(useHardwareBacked,anchor){const browserProxy=CertificatesBrowserProxyImpl.getInstance();if(this.certificateType===CertificateType.PERSONAL){browserProxy.importPersonalCertificate(useHardwareBacked).then((showPasswordPrompt=>{if(showPasswordPrompt){this.dispatchImportActionEvent_(null,anchor)}}),this.onRejected_.bind(this,anchor))}else if(this.certificateType===CertificateType.CA){browserProxy.importCaCertificate().then((certificateName=>{this.dispatchImportActionEvent_({name:certificateName},anchor)}),this.onRejected_.bind(this,anchor))}else if(this.certificateType===CertificateType.SERVER){browserProxy.importServerCertificate().catch(this.onRejected_.bind(this,anchor))}else{assertNotReached()}}}customElements.define(CertificateListElement.is,CertificateListElement);